function wankai()
{
   _parent.万解 = true;
   _parent.中转.ql = ql;
   _parent.中转.hp = hp;
   if(!wudi)
   {
      clearInterval(_root.feiint);
      _root.feiint = setInterval(feixue,1000);
   }
   _parent.nextFrame();
   _root._y = 0;
}

